import{_ as t,o as e,c as n,a6 as i}from"./chunks/framework.DycQjAfF.js";const l="/WareHouse/images/layout-gudang-blok-b-lantai-1.png",r="/WareHouse/images/layout-gudang-blok-a-lantai-2.png",m=JSON.parse('{"title":"Layout Gudang","description":"Denah Gudang Teknik Blok B lantai 1 dan Blok A lantai 2, beserta pembagian area penyimpanannya.","frontmatter":{"title":"Layout Gudang","description":"Denah Gudang Teknik Blok B lantai 1 dan Blok A lantai 2, beserta pembagian area penyimpanannya.","status":"perlu-verifikasi","catatan_status":"Denah Blok A lantai 2 dan Blok B lantai 1 (versi 6 April 2026) sudah dimuat. Bagian \\"Yang perlu dilengkapi\\" masih menunggu pembimbing.","diperbarui":"2026-10-15T00:00:00.000Z","kategori":"Alur Kerja","sumber":["ppt-gudang-teknik"],"kata_kunci":["layout","denah","lokasi","rak","zona","bin","penyimpanan","jalur evakuasi","blok a","blok b"]},"headers":[],"relativePath":"alur-kerja/layout-gudang.md","filePath":"alur-kerja/layout-gudang.md"}'),d={name:"alur-kerja/layout-gudang.md"};function o(s,a,u,g,p,k){return e(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="layout-gudang" tabindex="-1">Layout Gudang <a class="header-anchor" href="#layout-gudang" aria-label="Permalink to &quot;Layout Gudang&quot;">​</a></h1><p class="lead">Denah gudang membantu kamu menemukan lokasi barang dan memahami pembagian area. Gudang Teknik terbagi menjadi Blok B di lantai 1 dan Blok A di lantai 2.</p><h2 id="membaca-kode-lokasi" tabindex="-1">Membaca kode lokasi <a class="header-anchor" href="#membaca-kode-lokasi" aria-label="Permalink to &quot;Membaca kode lokasi&quot;">​</a></h2><p>Setiap area diberi kode dengan pola <strong>Blok.Area.Rak</strong>. Contohnya, <code>B.09.02</code> berarti Blok B, area 09 (alat tulis dan perlengkapan kantor), rak 02. Kode yang sama tertulis di papan kuning pada rak.</p><h2 id="blok-b-lantai-1" tabindex="-1">Blok B, lantai 1 <a class="header-anchor" href="#blok-b-lantai-1" aria-label="Permalink to &quot;Blok B, lantai 1&quot;">​</a></h2><figure><p><img src="'+l+'" alt="Denah Gudang Teknik Blok B lantai 1, berisi area B.01 sampai B.09, TPS scrap, dan pintu darurat"></p><figcaption>Denah Blok B lantai 1, versi 6 April 2026.</figcaption></figure><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Area</th><th>Isi atau fungsi</th></tr></thead><tbody><tr><td data-label="Area">B.01</td><td data-label="Isi atau fungsi">Penerimaan barang dari vendor atau supplier</td></tr><tr><td data-label="Area">B.02</td><td data-label="Isi atau fungsi">Pelayanan alat tulis dan suku cadang</td></tr><tr><td data-label="Area">B.03</td><td data-label="Isi atau fungsi">Wire rope dan webbing sling</td></tr><tr><td data-label="Area">B.04</td><td data-label="Isi atau fungsi">Material parts: bearing, lock nut, lock washer, perlengkapan keselamatan</td></tr><tr><td data-label="Area">B.05</td><td data-label="Isi atau fungsi">Consumable parts: elektroda las, cutting wheel, cutting ring, dan lainnya</td></tr><tr><td data-label="Area">B.06</td><td data-label="Isi atau fungsi">Equipment, material parts, material non-parts, dan parts lainnya</td></tr><tr><td data-label="Area">B.07</td><td data-label="Isi atau fungsi">Kantor gudang</td></tr><tr><td data-label="Area">B.08</td><td data-label="Isi atau fungsi">Bevel protector plastik ukuran ½&quot; sampai 2&quot; dan stopper pipe merah</td></tr><tr><td data-label="Area">B.09</td><td data-label="Isi atau fungsi">Alat tulis dan perlengkapan kantor</td></tr></tbody></table><p>Di Blok B juga ada <strong>TPS scrap</strong> (tempat penampungan sementara barang bekas) dan <strong>pintu darurat</strong> di dekat kantor gudang (B.07).</p><h2 id="blok-a-lantai-2" tabindex="-1">Blok A, lantai 2 <a class="header-anchor" href="#blok-a-lantai-2" aria-label="Permalink to &quot;Blok A, lantai 2&quot;">​</a></h2><figure><p><img src="'+r+'" alt="Denah Gudang Teknik Blok A lantai 2, berisi area A.01 sampai A.04"></p><figcaption>Denah Blok A lantai 2, versi 6 April 2026.</figcaption></figure><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Area</th><th>Isi atau fungsi</th></tr></thead><tbody><tr><td data-label="Area">A.01</td><td data-label="Isi atau fungsi">U-ring, O-ring, seal oil, packing, plastik transparan, tools, belt</td></tr><tr><td data-label="Area">A.02</td><td data-label="Isi atau fungsi">Baut, mur, pegas, clamp-U, connecting link, pipa tembaga</td></tr><tr><td data-label="Area">A.03</td><td data-label="Isi atau fungsi">Dokumen</td></tr><tr><td data-label="Area">A.04</td><td data-label="Isi atau fungsi">Dop plastik ukuran di atas 2&quot; dan end cup</td></tr></tbody></table><p>Dop plastik di A.04 dan bevel protector di B.08 disusun per ukuran dan warna, misalnya &quot;3&quot; BLUE&quot; atau &quot;1/2&quot; YELLOW&quot;.</p><h2 id="yang-perlu-dilengkapi" tabindex="-1">Yang perlu dilengkapi <a class="header-anchor" href="#yang-perlu-dilengkapi" aria-label="Permalink to &quot;Yang perlu dilengkapi&quot;">​</a></h2><p>Lengkapi bagian berikut bersama pembimbing:</p><ul class="daftar-periksa"><li>[x] <strong>Pembagian zona.</strong> Lihat tabel area di atas.</li><li><strong>Penomoran rak dan lokasi.</strong> Arti bagian terakhir kode lokasi di master material, misalnya <code>025</code> pada <code>B.09.02.025</code>.</li><li><strong>Area khusus.</strong> Lokasi penyimpanan consumable seperti oli dan grease, APD, serta barang berat.</li><li><strong>Jalur dan pintu darurat.</strong> Lokasi alat pemadam api ringan (APAR) dan titik kumpul.</li><li><strong>Area terbatas.</strong> Bagian yang tidak boleh dimasuki peserta magang tanpa pendamping.</li></ul>',15)])])}const c=t(d,[["render",o]]);export{m as __pageData,c as default};
